      @Override
      public InitializeProcessingOutCtx initializeProcessing(InitializeProcessingInCtx methodIn) throws Exception {
      
// *    Initialization (program & request) processing               *
// ******************************************************************

// *    * Initialize program (on first call only) *
Ar640010Ctx programCtx = methodIn.getAr640010Ctx();
InitializeProcessingOutCtx methodOut = methodIn.getInitializeProcessingOutCtx();
//  IF 88-100-FIRST-CALL-TO-MODULE
          if ( methodIn.isFirstCallToModule88100()  ) { 
//  PERFORM 1100-INITIALIZE-PROGRAM
              initializeProgram(programCtx);/*1100-INITIALIZE-PROGRAM*/
          }
//  PERFORM 1200-INITIALIZE-REQUEST
          initializeRequest(programCtx);/*1200-INITIALIZE-REQUEST*/

// *    * Initialize request *

// *    * Initialize control file elements (on first call only) *
//  IF 88-100-FIRST-CALL-TO-MODULE
          if ( methodIn.isFirstCallToModule88100()  ) { 
//  PERFORM 1300-INITIALIZE-CONTROL
              initializeControl(programCtx.getInitializeControlInCtx());/*1300-INITIALIZE-CONTROL*/
          }
//  PERFORM 1400-INITIALIZE-CONNECTIVITY
          initializeConnectivity(programCtx.getInitializeConnectivityInCtx());/*1400-INITIALIZE-CONNECTIVITY*/

// *    * Initialize (database) connectivity *

// *    * Initialize (dynamic) allocation linkage (when required) *
//  IF 88-110-REQUEST-FAILED OR 88-1000-COUNT-FILES OR 88-1000-RESET-FILE
//  ELSE
          if (!(methodIn.isRequestFailed88110())  && !(methodIn.isCountFiles881000())  && !(methodIn.isResetFile881000()) ) { 
//  PERFORM 1500-INITIALIZE-ALLOCATION
              initializeAllocation(programCtx.getInitializeAllocationInCtx());/*1500-INITIALIZE-ALLOCATION*/
          }

// *    * Signal 'first call' has been completed *

// *    Extract taraxtk parameters
//  SET 88-100-FIRST-CALL-COMPLETED TO TRUE
          methodOut.setFirstCallCompleted88100True(); 
          
//  IF 88-110-REQUEST-SUCCESSFUL
          if ( methodIn.isRequestSuccessful88110()  ) { 
//  PERFORM 1600-EXTRACT-TARAXTK-INFO
              extractTaraxtkInfo(programCtx.getExtractTaraxtkInfoInCtx());/*1600-EXTRACT-TARAXTK-INFO*/
          }
      
      return methodOut;
      }
