      public int call(ProgramContext ctx, Object[] params) throws Exception {
      Ar640010Ctx programCtx = (Ar640010Ctx) ctx;
      
      int len = params.length;
         if (len > 0 && params[0] != null )
            programCtx.getIdentityParms1000().set((Field)params[0]);
         if (len > 1 && params[1] != null )
            programCtx.getRequestParms1000().set((Field)params[1]);
         if (len > 2 && params[2] != null )
            programCtx.getResponseParms1000().set((Field)params[2]);
         if (len > 3 && params[3] != null )
            programCtx.getDynamLinkArea1100().set((Field)params[3]);
         // invoke the process and return rc
         return process(programCtx);
         
      }
      
      public int call(ProgramContext ctx, Field... parameters) throws Exception {
      Ar640010Ctx programCtx = (Ar640010Ctx) ctx;
         for (int index = 0; index < parameters.length;index++) {
             switch(index) {
              case 0:
                      if(parameters[index] != null ) {
              		if (parameters[index] instanceof IdentityParms1000) {
                       	programCtx.setIdentityParms1000((IdentityParms1000) parameters[index]);
                  	} else {
                       	programCtx.getIdentityParms1000().set(parameters[index]);
                  	}
                  }
                
                  break;
              case 1:
                      if(parameters[index] != null ) {
              		if (parameters[index] instanceof RequestParms1000) {
                       	programCtx.setRequestParms1000((RequestParms1000) parameters[index]);
                  	} else {
                       	programCtx.getRequestParms1000().set(parameters[index]);
                  	}
                  }
                
                  break;
              case 2:
                      if(parameters[index] != null ) {
              		if (parameters[index] instanceof ResponseParms1000) {
                       	programCtx.setResponseParms1000((ResponseParms1000) parameters[index]);
                  	} else {
                       	programCtx.getResponseParms1000().set(parameters[index]);
                  	}
                  }
                
                  break;
              case 3:
                      if(parameters[index] != null ) {
              		if (parameters[index] instanceof DynamLinkArea1100) {
                       	programCtx.setDynamLinkArea1100((DynamLinkArea1100) parameters[index]);
                  	} else {
                       	programCtx.getDynamLinkArea1100().set(parameters[index]);
                  	}
                  }
                
                  break;
            }
         }
      	return process(programCtx);
      }
      
      
